SELECT ?point ?ts WHERE {
  ?point brick:hasLocation ?zone .
  ?zone ref:hasIdentifier ?zid .
  ?point ref:hasTimeseriesId ?ts .
  FILTER(str(?zid) = "Perimeter_bot_ZN_3")
}

SELECT ?z ?zid ?pl WHERE {
  ?point brick:hasLocation ?z .
  ?point ref:hasTimeseriesId ?ts .
  ?point ref:hasLabel ?pl .
  FILTER(str(?z) LIKE "%Perimeter_bot_ZN_3%")
}

SELECT ?z WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) LIKE "%Perimeter_bot_ZN_3%")
}

SELECT ?z WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) LIKE "%ZN_3%")
}

